def periksa_nilai(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("harus bilangan bulat")
    if n < 0 or n > 100:
        raise ValueError("di luar rentang")
    return n

def muat_semua(daftar):
    hasil, gagal = [], []
    for s in daftar:
        try:
            hasil.append(float(s))
        except ValueError:
            gagal.append(s)
    return hasil, gagal

